(() => {
'use strict';
const host=document.getElementById('folder-projects'),status=document.getElementById('folder-status'),search=document.getElementById('work-search'),select=document.getElementById('work-topic'),button=document.getElementById('refresh-work');
const list=document.getElementById('project-list');
const extras=[['Perdue Farms','2023','Enterprise treasury & payments','SAP S/4HANA Treasury, Bank Account Management, liquidity planning and Agile design playbacks.','BAM · Liquidity · S/4HANA'],['MSC Industrial Direct','2023–24','S/4HANA Voyager transformation','Clean-core treasury architecture across BCM and liquidity workflows, supported by Signavio process work and Agile playbacks.','Clean core · BCM · Signavio']];
for(const [client,date,title,description,tags] of extras){const article=document.createElement('article');for(const [tag,text,cls] of [['div',date,'meta'],['h3',client],['h4',title],['p',description],['p',tags,'small']]){const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;article.append(e)}list.append(article)}
const cards=[...list.children];let data=window.PORTFOLIO_WORK;
function element(tag,text,cls){const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e}
function filter(){const query=search.value.trim().toLowerCase(),topic=select.value.toLowerCase();let visible=0;for(const c of [...cards,...host.children]){const text=c.textContent.toLowerCase();c.hidden=!(text.includes(query)&&(!topic||text.includes(topic)));if(!c.hidden&&cards.includes(c))visible++}document.getElementById('work-results').textContent=`${visible} selected engagement${visible===1?'':'s'}${query||topic?' match your search':''}`;}
function render(value){data=value;host.replaceChildren();const previous=select.value;select.replaceChildren(new Option('All focus areas',''));const names=new Set();for(const project of value.projects){if(!project.connected||!project.topics.length)continue;const article=element('article','','folder-card');article.append(element('p','PROJECT MATERIALS / '+project.client,'eyebrow'),element('h3',project.client));const tags=element('div','','tags');for(const topic of project.topics){names.add(topic.name);tags.append(element('span',topic.name));}article.append(tags);const details=element('details','');details.append(element('summary','Explore themes +'));for(const topic of project.topics){details.append(element('h5',topic.name),element('p',topic.description+'.'));}details.append(element('p','These themes are detected in project materials and describe the work represented; they do not establish ownership of every document or measured business outcomes.','small'));article.append(details);host.append(article)}for(const name of [...names].sort())select.add(new Option(name,name));select.value=previous;
const partial=value.projects.some(p=>p.warning||p.unreadableCount);status.textContent=`Project themes updated ${new Date(value.updatedAt).toLocaleString()}.`;filter();}
async function poll(){try{const response=await fetch('data/work.json',{cache:'no-store'});if(!response.ok)throw Error();const next=await response.json();if(!data||next.updatedAt!==data.updatedAt)render(next);if(response.headers.get('X-Sync-Warning'))status.textContent='Showing saved work. The latest folder sync failed; check the local app terminal.';}catch{status.textContent='Showing saved project themes. '}}
search.addEventListener('input',filter);select.addEventListener('change',filter);
button.addEventListener('click',async()=>{button.disabled=true;status.textContent='Updating project themes…';try{const response=await fetch('/api/refresh',{method:'POST'});if(!response.ok)throw Error();render(await response.json());}catch{status.textContent='Could not refresh folders. Check the local app terminal.'}finally{button.disabled=false}});
if(data)render(data);else filter();
if(location.hostname==='127.0.0.1'&&location.port){button.hidden=false;poll();setInterval(poll,10000)}
})();
